package com.campusvibe.controller;
import com.campusvibe.entity.Event; import com.campusvibe.repository.EventRepository; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/events") public class EventController {final EventRepository repo; public EventController(EventRepository r){repo=r;} @GetMapping public List<Event> all(@RequestParam(required=false) String search){return search==null||search.isBlank()?repo.findAll():repo.findByNameContainingIgnoreCase(search);} @GetMapping("/{id}") public Event one(@PathVariable Long id){return repo.findById(id).orElseThrow();} @PostMapping @PreAuthorize("hasAnyRole('ADMIN','COORDINATOR')") public Event create(@RequestBody Event e){return repo.save(e);} @PutMapping("/{id}") @PreAuthorize("hasAnyRole('ADMIN','COORDINATOR')") public Event update(@PathVariable Long id,@RequestBody Event e){e.id=id;return repo.save(e);} @DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public void delete(@PathVariable Long id){repo.deleteById(id);} }
